//! noevia#1318 slice 14: native `GET /api/v1/search` and `GET /api/v1/search/repo` through the
//! real router.
//!
//! Every case of `fixtures/search-python.v1.json` (the actual services Python, regenerated by CI
//! from the pinned ref) runs through the router against a fake Hub and a fake Python child: the
//! status, content type, body, Hub requests and avatar cache must match. The route policy (which
//! paths, methods and spellings are native), the token gate and the answers for a refusal, an
//! unreachable child and a failed handler are checked beside it. Every name is synthetic.
#![cfg(feature = "native-search")]
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]
use axum::{
    body::Body,
    http::{Method, Request},
};
use http_body_util::BodyExt;
use noevia_model_manager::{
    search::{Hub, Search, Timeouts, REFUSAL},
    search_route, Container, DockerRead, Redactor, SearchRoute, StateData,
};
use serde_json::{json, Value};
use std::{
    future::Future,
    path::Path,
    pin::Pin,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc, Mutex,
    },
    time::Duration,
};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tower::ServiceExt;

const TOKEN: &str = "synthetic-model-loader-token-0123456789abcdef";

type Job<'a, T> = Pin<Box<dyn Future<Output = Result<T, &'static str>> + Send + 'a>>;

struct NoDocker;

impl DockerRead for NoDocker {
    fn containers(&self) -> Job<'_, Vec<Container>> {
        Box::pin(async { Err("not used") })
    }
    fn logs<'a>(&'a self, _: &'a str, _: usize) -> Job<'a, Vec<u8>> {
        Box::pin(async { Err("not used") })
    }
}

fn state(search: Option<Search>, legacy_base: &str) -> Arc<StateData> {
    Arc::new(StateData {
        #[cfg(feature = "native-diagnose")]
        diagnosis: None,
        #[cfg(feature = "native-prompts")]
        prompts: None,
        #[cfg(feature = "native-settings")]
        settings: None,
        #[cfg(feature = "native-model-list")]
        model_list: None,
        model_updates: None,
        model_detail: None,
        sections: None,
        embedding: None,
        host: None,
        token: TOKEN.into(),
        configured: vec![],
        docker: Arc::new(NoDocker),
        redactor: Redactor::new().unwrap(),
        permits: tokio::sync::Semaphore::new(4),
        legacy: noevia_model_manager::legacy_client().unwrap(),
        legacy_base: legacy_base.into(),
        idle_unload: None,
        #[cfg(feature = "native-section-autoconfig")]
        section_autoconfig: None,
        #[cfg(feature = "native-download-targets")]
        download_targets: None,
        #[cfg(feature = "native-badges")]
        badges: None,
        #[cfg(feature = "native-bench-runs")]
        bench_runs: None,
        #[cfg(feature = "native-section-writes")]
        section_writes: None,
        #[cfg(feature = "native-settings-write")]
        settings_write: None,
        #[cfg(feature = "native-benchmark-overview")]
        benchmark_overview: None,
        #[cfg(feature = "native-check-updates")]
        check_updates: None,
        #[cfg(feature = "native-downloads")]
        downloads: None,
        #[cfg(feature = "native-model-delete")]
        model_delete: None,
        #[cfg(feature = "native-draft-heads")]
        draft_heads: None,
        search: search.map(Arc::new),
        #[cfg(feature = "native-backends")]
        backend_stats: None,
        #[cfg(feature = "native-benchmark-runner")]
        bench_runner: None,
        #[cfg(feature = "native-backend-control")]
        backends: None,
    })
}

async fn call(
    state: Arc<StateData>,
    method: &str,
    uri: &str,
    token: bool,
) -> (u16, Option<String>, String) {
    let mut request = Request::builder().method(method).uri(uri);
    if token {
        request = request.header("x-model-loader-token", TOKEN);
    }
    let response = noevia_model_manager::router(state)
        .oneshot(request.body(Body::empty()).unwrap())
        .await
        .unwrap();
    let status = response.status().as_u16();
    let kind = response
        .headers()
        .get("content-type")
        .map(|v| v.to_str().unwrap().to_owned());
    let bytes = response.into_body().collect().await.unwrap().to_bytes();
    (status, kind, String::from_utf8(bytes.to_vec()).unwrap())
}

fn closed_port() -> String {
    let closed = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let base = format!("http://127.0.0.1:{}", closed.local_addr().unwrap().port());
    drop(closed);
    base
}

fn clock() -> f64 {
    f64::from_bits(CLOCK.load(Ordering::SeqCst))
}

static CLOCK: AtomicU64 = AtomicU64::new(0);

#[test]
fn route_shapes() {
    let get = Method::GET;
    for (path, route) in [
        ("/api/v1/search", Some(SearchRoute::Search)),
        ("/api/v1/search/repo", Some(SearchRoute::Repo)),
        // Starlette routes the decoded path.
        ("/api/v1/%73earch", Some(SearchRoute::Search)),
        ("/api/v1/search%2Frepo", Some(SearchRoute::Repo)),
        ("/api/v1%2Fsearch", Some(SearchRoute::Search)),
        ("/api/v1/search/", None),
        ("/api/v1/search/repo/", None),
        ("/api/v1/search/repos", None),
        ("/api/v1/searches", None),
        ("/api/v1/search/repo/x", None),
        ("/api/v1", None),
        ("/search", None),
    ] {
        assert_eq!(search_route(&get, path), route, "{path}");
    }
    for method in [Method::POST, Method::HEAD, Method::PUT, Method::DELETE] {
        assert_eq!(search_route(&method, "/api/v1/search"), None);
        assert_eq!(search_route(&method, "/api/v1/search/repo"), None);
    }
}

/// Another method answers FastAPI's 405 and a slash variant the front's 404 (its route policy,
/// as without the native search); a request without the token is refused first.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn unowned_requests_are_not_answered_natively() {
    let dir = tempfile::tempdir().unwrap();
    let search = Search::new(dir.path(), "http://127.0.0.1:1", TOKEN).unwrap();
    let shared = state(Some(search), &closed_port());
    for (method, uri, expected) in [
        ("POST", "/api/v1/search", 405),
        ("PUT", "/api/v1/search/repo?repo=a%2Fb", 405),
        ("GET", "/api/v1/search/", 404),
        ("GET", "/api/v1/search/repo/", 404),
    ] {
        let (status, _, body) = call(shared.clone(), method, uri, true).await;
        assert_eq!(status, expected, "{method} {uri}: {body}");
        assert!(!body.contains(REFUSAL), "{method} {uri}");
    }
    for uri in ["/api/v1/search", "/api/v1/search/repo?repo=a%2Fb"] {
        let (status, _, body) = call(shared.clone(), "GET", uri, false).await;
        assert_eq!(status, 401, "{uri}");
        assert_eq!(body, r#"{"error":"unauthorized"}"#);
    }
}

type Seen = Arc<Mutex<Vec<Value>>>;

fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
        .collect()
}

fn header_of(head: &str, name: &str) -> Option<String> {
    head.split("\r\n")
        .filter_map(|l| l.split_once(':'))
        .find(|(k, _)| k.eq_ignore_ascii_case(name))
        .map(|(_, v)| v.trim().to_owned())
}

async fn read_head(sock: &mut tokio::net::TcpStream) -> Option<String> {
    let mut head = Vec::new();
    let mut byte = [0u8; 1];
    while !head.ends_with(b"\r\n\r\n") {
        if sock.read(&mut byte).await.unwrap_or(0) == 0 {
            return None;
        }
        head.push(byte[0]);
    }
    Some(String::from_utf8_lossy(&head).into_owned())
}

type Answers = Arc<Mutex<Value>>;

async fn hub(answers: Answers, other: String) -> (String, Seen, tokio::task::JoinHandle<()>) {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let base = format!("http://127.0.0.1:{}", listener.local_addr().unwrap().port());
    let seen: Seen = Arc::new(Mutex::new(Vec::new()));
    let (b, s) = (base.clone(), seen.clone());
    let task = tokio::spawn(async move {
        while let Ok((mut sock, _)) = listener.accept().await {
            let (answers, base, seen, other) =
                (answers.clone(), b.clone(), s.clone(), other.clone());
            tokio::spawn(async move {
                let Some(text) = read_head(&mut sock).await else {
                    return;
                };
                let path = text
                    .split("\r\n")
                    .next()
                    .unwrap()
                    .split(' ')
                    .nth(1)
                    .unwrap()
                    .to_owned();
                seen.lock().unwrap().push(json!({
                    "path": path,
                    "authorization": header_of(&text, "authorization").map_or(Value::Null, Value::String),
                    "range": header_of(&text, "range").map_or(Value::Null, Value::String),
                }));
                let found = answers.lock().unwrap().get(&path).cloned();
                let (status, headers, body, extra) = match found {
                    Some(a) => {
                        let mut body = hex(a["body"].as_str().unwrap());
                        body.resize(body.len() + a["zeros"].as_u64().unwrap_or(0) as usize, 0);
                        (
                            a["status"].as_u64().unwrap(),
                            a["headers"].as_array().unwrap().clone(),
                            body,
                            a.clone(),
                        )
                    }
                    None => (
                        404,
                        vec![json!(["content-type", "application/json"])],
                        br#"{"error":"Repository not found"}"#.to_vec(),
                        Value::Null,
                    ),
                };
                if let Some(delay) = extra["delay"].as_f64() {
                    tokio::time::sleep(Duration::from_secs_f64(delay)).await;
                }
                if extra["mode"] == "drop" {
                    return;
                }
                let mut out = format!("HTTP/1.1 {status} X\r\n");
                for h in headers {
                    out.push_str(&format!(
                        "{}: {}\r\n",
                        h[0].as_str().unwrap(),
                        h[1].as_str()
                            .unwrap()
                            .replace("@HUB@", &base)
                            .replace("@CDN@", &other)
                    ));
                }
                let declared = body.len() + if extra["mode"] == "partial" { 100 } else { 0 };
                out.push_str(&format!(
                    "content-length: {declared}\r\nconnection: close\r\n\r\n"
                ));
                let _ = sock.write_all(out.as_bytes()).await;
                let _ = sock.write_all(&body).await;
                let _ = sock.shutdown().await;
            });
        }
    });
    (base, seen, task)
}

#[derive(Default)]
struct Script {
    search: Option<Value>,
    repo: Option<Value>,
    problems: Vec<String>,
}

async fn child() -> (String, Arc<Mutex<Script>>, tokio::task::JoinHandle<()>) {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let base = format!("http://127.0.0.1:{}", listener.local_addr().unwrap().port());
    let script: Arc<Mutex<Script>> = Arc::new(Mutex::new(Script::default()));
    let s = script.clone();
    let task = tokio::spawn(async move {
        while let Ok((mut sock, _)) = listener.accept().await {
            let script = s.clone();
            tokio::spawn(async move {
                let Some(text) = read_head(&mut sock).await else {
                    return;
                };
                let mut first = text.split("\r\n").next().unwrap().split(' ');
                let (method, path) = (first.next().unwrap(), first.next().unwrap().to_owned());
                let length: usize = header_of(&text, "content-length")
                    .and_then(|v| v.parse().ok())
                    .unwrap_or(0);
                let mut body = vec![0u8; length];
                sock.read_exact(&mut body).await.unwrap();
                let token = header_of(&text, "x-model-loader-token");
                let (status, answer) = {
                    let mut script = script.lock().unwrap();
                    if token.as_deref() != Some(TOKEN) {
                        script.problems.push(format!("token {token:?} on {path}"));
                    }
                    let scripted = match (method, path.as_str()) {
                        ("GET", "/api/v1/internal/search-runtime") => script.search.clone(),
                        ("POST", "/api/v1/internal/search-repo-runtime") => {
                            let got: Value = serde_json::from_slice(&body).unwrap_or(Value::Null);
                            let r = script.repo.clone();
                            if let Some(r) = &r {
                                if got != r["request"] {
                                    script
                                        .problems
                                        .push(format!("body {got} != {}", r["request"]));
                                }
                            }
                            r
                        }
                        _ => None,
                    };
                    match scripted {
                        Some(r) => (
                            r["status"].as_u64().unwrap(),
                            r["body"].as_str().unwrap().to_owned(),
                        ),
                        None => {
                            script.problems.push(format!("unexpected {method} {path}"));
                            (500, String::new())
                        }
                    }
                };
                let out = format!(
                    "HTTP/1.1 {status} X\r\ncontent-type: application/json\r\nconnection: close\r\ncontent-length: {}\r\n\r\n{answer}",
                    answer.len()
                );
                let _ = sock.write_all(out.as_bytes()).await;
                let _ = sock.shutdown().await;
            });
        }
    });
    (base, script, task)
}

fn store(data: &Path, schema: &Value, seed: &Value) {
    let db = rusqlite::Connection::open(data.join("model_loader.db")).unwrap();
    for sql in schema.as_array().unwrap() {
        db.execute_batch(sql.as_str().unwrap()).unwrap();
    }
    db.execute("DELETE FROM kv", []).unwrap();
    for sql in seed.as_array().into_iter().flatten() {
        db.execute_batch(sql.as_str().unwrap()).unwrap();
    }
}

fn avatars(data: &Path) -> Value {
    let db = rusqlite::Connection::open(data.join("model_loader.db")).unwrap();
    let mut statement = db
        .prepare("SELECT owner, url, fetched_at FROM avatar_cache ORDER BY owner")
        .unwrap();
    let rows: Vec<Value> = statement
        .query_map([], |row| {
            let cell = |i: usize| -> rusqlite::Result<Value> {
                use rusqlite::types::ValueRef;
                Ok(match row.get_ref(i)? {
                    ValueRef::Integer(n) => json!(n),
                    ValueRef::Real(f) => json!(f),
                    ValueRef::Text(t) => Value::String(String::from_utf8(t.to_vec()).unwrap()),
                    other => panic!("{other:?}"),
                })
            };
            Ok(Value::Array(vec![cell(0)?, cell(1)?, cell(2)?]))
        })
        .unwrap()
        .map(Result::unwrap)
        .collect();
    Value::Array(rows)
}

fn sorted(seen: &Seen) -> Value {
    let mut rows = seen.lock().unwrap().clone();
    rows.sort_by_key(|r| {
        (
            r["path"].as_str().unwrap().to_owned(),
            r["authorization"].as_str().unwrap_or("").to_owned(),
            r["range"].as_str().unwrap_or("").to_owned(),
        )
    });
    Value::Array(rows)
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn actual_python_differential_through_the_router() {
    let fixture: Value =
        serde_json::from_str(include_str!("fixtures/search-python.v1.json")).unwrap();
    let mut compared = 0;
    for case in fixture["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let dir = tempfile::tempdir().unwrap();
        store(dir.path(), &fixture["schema"], &case["seed"]);
        let answers: Answers = Arc::new(Mutex::new(case["hub"].clone()));
        let cdn_answers: Answers = Arc::new(Mutex::new(case["cdn"].clone()));
        let (cdn_base, cdn_seen, cdn_task) = hub(cdn_answers, String::new()).await;
        let (base, seen, hub_task) = hub(answers.clone(), cdn_base).await;
        let (child_base, script, child_task) = child().await;
        let hub_base = if case["hub_down"].as_bool() == Some(true) {
            closed_port()
        } else {
            base
        };
        let wait = Duration::from_millis(1000);
        let search = Search::with(
            dir.path(),
            Hub {
                api: format!("{hub_base}/api"),
                resolve: hub_base.clone(),
            },
            &child_base,
            TOKEN,
            clock,
            Timeouts {
                search: wait,
                tree: wait,
                header: wait,
                avatar: wait,
                listings: Duration::from_secs(60),
            },
        )
        .unwrap();
        let shared = state(Some(search), &closed_port());
        for (index, step) in case["results"].as_array().unwrap().iter().enumerate() {
            let get = step["get"].as_str().unwrap();
            CLOCK.store(step["now"].as_f64().unwrap().to_bits(), Ordering::SeqCst);
            seen.lock().unwrap().clear();
            cdn_seen.lock().unwrap().clear();
            if index > 0 {
                if let Some(more) = case["then_hub"].as_object() {
                    let mut all = answers.lock().unwrap();
                    for (k, v) in more {
                        all[k.as_str()] = v.clone();
                    }
                }
            }
            {
                let mut script = script.lock().unwrap();
                script.problems.clear();
                let runtime = &step["runtime"];
                let slot = (!runtime.is_null()).then(|| runtime.clone());
                if get.starts_with("/api/v1/search/repo") {
                    (script.search, script.repo) = (None, slot);
                } else {
                    (script.search, script.repo) = (slot, None);
                }
            }
            let (status, kind, body) = call(shared.clone(), "GET", get, true).await;
            let ctx = format!("{id} {get}");
            if case["native"] == "refused" {
                assert_eq!(status, 503, "{ctx}: {body}");
                assert_eq!(body, json!({ "detail": REFUSAL }).to_string(), "{ctx}");
                continue;
            }
            assert_eq!(
                u64::from(status),
                step["status"].as_u64().unwrap(),
                "{ctx}: {body}"
            );
            assert_eq!(kind.as_deref(), step["content_type"].as_str(), "{ctx}");
            assert_eq!(body, step["body"].as_str().unwrap(), "{ctx}");
            if case["native_requests"] != "unchecked" {
                assert_eq!(sorted(&seen), step["requests"], "{ctx}: Hub requests");
            }
            if case["cdn"].is_object() {
                assert_eq!(
                    sorted(&cdn_seen),
                    step["cdn_requests"],
                    "{ctx}: CDN requests"
                );
            }
            assert_eq!(avatars(dir.path()), step["avatars"], "{ctx}: avatar cache");
            let script = script.lock().unwrap();
            assert!(script.problems.is_empty(), "{ctx}: {:?}", script.problems);
            compared += 1;
        }
        hub_task.abort();
        cdn_task.abort();
        child_task.abort();
    }
    assert!(compared >= 150, "{compared}");
}

/// A refusal is the native 503, an unreachable child the forwarded 502, a failed handler the plain
/// 500, and the 422 FastAPI's.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn refusal_bad_gateway_and_failure_answers() {
    let dir = tempfile::tempdir().unwrap();
    let fixture: Value =
        serde_json::from_str(include_str!("fixtures/search-python.v1.json")).unwrap();
    store(dir.path(), &fixture["schema"], &Value::Null);
    let item = json!({"id": "lab-one/m-GGUF", "downloads": 1, "likes": 0, "tags": ["gguf"]});
    let answer = |body: &Value| {
        json!({"status": 200, "headers": [["content-type", "application/json"]],
               "body": body.to_string().bytes().map(|b| format!("{b:02x}")).collect::<String>()})
    };
    let models = "/api/models?limit=30&sort=trendingScore&direction=-1&filter=gguf";
    let answers: Answers = Arc::new(Mutex::new(json!({models: answer(&json!([item]))})));
    let (base, _, hub_task) = hub(answers, String::new()).await;
    let search = Search::with(
        dir.path(),
        Hub {
            api: format!("{base}/api"),
            resolve: base.clone(),
        },
        &closed_port(),
        TOKEN,
        clock,
        Timeouts::default(),
    )
    .unwrap();
    let shared = state(Some(search), &closed_port());
    // The child is down: after the Hub answered, 502.
    let (status, kind, body) = call(shared.clone(), "GET", "/api/v1/search", true).await;
    assert_eq!(status, 502, "{body}");
    assert_eq!(kind.as_deref(), Some("application/json"));
    assert_eq!(body, r#"{"detail":"Python-owned endpoint unavailable"}"#);
    // A value pydantic reads in a way this side does not reproduce: the refusal.
    let (status, kind, body) = call(shared.clone(), "GET", "/api/v1/search?limit=3_0", true).await;
    assert_eq!(status, 503);
    assert_eq!(kind.as_deref(), Some("application/json"));
    assert_eq!(body, json!({ "detail": REFUSAL }).to_string());
    // FastAPI's 422, and the missing repo.
    let (status, kind, body) = call(shared.clone(), "GET", "/api/v1/search?vision=zz", true).await;
    assert_eq!(status, 422);
    assert_eq!(kind.as_deref(), Some("application/json"));
    assert!(
        body.starts_with(r#"{"detail":[{"type":"bool_parsing""#),
        "{body}"
    );
    let (status, _, body) = call(shared.clone(), "GET", "/api/v1/search/repo", true).await;
    assert_eq!(status, 422, "{body}");
    // The Hub's own failure for the repository is a 200 with the error (Python's answer).
    let (status, _, body) = call(
        shared,
        "GET",
        "/api/v1/search/repo?repo=lab-one%2Fm-GGUF",
        true,
    )
    .await;
    assert_eq!(status, 200);
    assert_eq!(
        body,
        r#"{"repo":"lab-one/m-GGUF","error":"Hugging Face returned HTTP 404","groups":[]}"#
    );
    hub_task.abort();
}

/// With no native search (the default) the paths are forwarded to the child like any other.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn without_the_native_search_the_routes_are_forwarded() {
    let shared = state(None, &closed_port());
    for uri in ["/api/v1/search", "/api/v1/search/repo?repo=a%2Fb"] {
        let (status, _, body) = call(shared.clone(), "GET", uri, true).await;
        assert_eq!(status, 502, "{uri}: {body}");
    }
}

/// The child's private calls are the parent's own: a client cannot reach them through the front's
/// forwarder, in any spelling, with the native search on or off. The child sees nothing.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_client_cannot_reach_the_private_search_calls() {
    let (child_base, script, child_task) = child().await;
    let dir = tempfile::tempdir().unwrap();
    for native in [true, false] {
        let search = native.then(|| Search::new(dir.path(), &child_base, TOKEN).unwrap());
        // The front forwards to the child's address, so a leak would reach the fake.
        let shared = state(search, &child_base);
        for method in ["GET", "POST", "PUT"] {
            for uri in [
                "/api/v1/internal/search-runtime",
                "/api/v1/internal/search-repo-runtime",
                "/api/v1/internal/search-runtime?x=1",
                "/api/v1/INTERNAL/search-runtime",
                "/api/v1/%69nternal/search-runtime",
                "/api/v1/internal%2Fsearch-repo-runtime",
                "/api/v1/%2569nternal/search-runtime",
                "/api/v1/%2e%2e/v1/internal/search-runtime",
                "/api/v1/./internal/search-runtime",
                "/api/v1//internal/search-runtime",
            ] {
                let (status, _, body) = call(shared.clone(), method, uri, true).await;
                assert!(
                    status == 404 || status == 405,
                    "{method} {uri}: {status} {body}"
                );
                assert!(!body.contains("runtime\":"), "{method} {uri}: {body}");
            }
        }
    }
    assert!(
        script.lock().unwrap().problems.is_empty(),
        "the child was reached: {:?}",
        script.lock().unwrap().problems
    );
    child_task.abort();
}
